package com.lkr2312.mintune;

import android.Manifest;
import android.app.Activity;
import android.app.AlertDialog;
import android.content.ContentUris;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.database.Cursor;
import android.graphics.Color;
import android.os.Build;
import android.os.Bundle;
import android.provider.MediaStore;
import android.text.InputType;
import android.view.Gravity;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.SeekBar;
import android.widget.Switch;
import android.widget.TextView;
import android.widget.Toast;
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public final class MainActivity extends Activity {
    private static final int REQUEST_AUDIO = 1001;
    private static final int BG = Color.rgb(8,26,48), SURFACE = Color.rgb(18,43,72), ALT = Color.rgb(25,55,87), MINT = Color.rgb(94,234,212), MUTED = Color.rgb(168,184,204);
    private final List<LibraryDbHelper.Track> tracks = new ArrayList<>(), recent = new ArrayList<>();
    private final ExecutorService executor = Executors.newSingleThreadExecutor();
    private LibraryDbHelper database; private LinearLayout pageHost, bottomNav; private EditText search; private TextView pageTitle, pageSubtitle, status; private int page, playingIndex = -1;
    @Override public void onCreate(Bundle state) { super.onCreate(state); if (Build.VERSION.SDK_INT >= 30) getWindow().setDecorFitsSystemWindows(true); getWindow().setStatusBarColor(BG); getWindow().setNavigationBarColor(BG); database = new LibraryDbHelper(this); buildShell(); if (hasAudioPermission()) loadData(); else requestAudioPermission(); }
    private void buildShell() { final int pad=dp(18); LinearLayout root=column(); root.setBackgroundColor(BG); root.setPadding(pad,dp(12),pad,dp(8)); root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(pad,dp(12)+i.getSystemWindowInsetTop(),pad,dp(8)+i.getSystemWindowInsetBottom());return i;}); LinearLayout header=column(), titleRow=row(), copy=column(); pageTitle=text("今日聆听",25,Color.WHITE); pageTitle.setTypeface(null,1); pageSubtitle=text("你的私人音乐空间",13,MUTED); copy.addView(pageTitle); copy.addView(pageSubtitle,lp(-1,dp(24))); titleRow.addView(copy,lp(0,-2,1)); TextView logo=text("M",32,MINT); logo.setGravity(Gravity.CENTER); logo.setBackgroundColor(ALT); titleRow.addView(logo,lp(dp(52),dp(52))); header.addView(titleRow); root.addView(header); pageHost=column(); root.addView(pageHost,lp(-1,0,1)); bottomNav=row(); bottomNav.setPadding(0,dp(8),0,0); root.addView(bottomNav,lp(-1,dp(62))); setContentView(root); switchPage(0); }
    private void switchPage(int target) { page=target; pageHost.removeAllViews(); String[] titles={"今日聆听","音乐库","歌单","设置"}, subs={"你的私人音乐空间","搜索和管理本地音乐","整理你的音乐收藏","让播放体验更贴近你"}; pageTitle.setText(titles[target]); pageSubtitle.setText(subs[target]); if(target==0) renderHome(); else if(target==1) renderLibrary(); else if(target==2) renderPlaylists(); else renderSettings(); renderBottomNav(); }
    private void renderBottomNav() { bottomNav.removeAllViews(); String[] labels={"今日聆听","音乐库","歌单","设置"}, icons={"⌂","♫","▣","⚙"}; for(int i=0;i<4;i++){final int tab=i; LinearLayout item=column(); item.setGravity(Gravity.CENTER); TextView ic=text(icons[i],20,page==i?MINT:MUTED); ic.setGravity(Gravity.CENTER); item.addView(ic,lp(-1,dp(25))); TextView label=text(labels[i],11,page==i?MINT:MUTED); label.setGravity(Gravity.CENTER); item.addView(label,lp(-1,dp(22))); item.setOnClickListener(v->switchPage(tab)); bottomNav.addView(item,lp(0,dp(52),1));} }
    private void renderHome() { ScrollView scroll=new ScrollView(this); LinearLayout body=column(); body.setPadding(0,dp(18),0,dp(18)); scroll.addView(body); pageHost.addView(scroll,lp(-1,0,1)); LinearLayout hero=card(); TextView ht=text(tracks.isEmpty()?"还没有音乐":"准备好继续聆听",23,Color.WHITE); ht.setTypeface(null,1); hero.addView(ht); TextView sub=text(tracks.isEmpty()?"前往音乐库扫描设备中的本地音频，开始你的第一次聆听。":"本地音乐、歌单和播放记录都保存在设备上。",14,MUTED); sub.setPadding(0,dp(8),0,dp(14)); hero.addView(sub); Button act=button(tracks.isEmpty()?"去扫描音乐":"打开音乐库"); act.setOnClickListener(v->switchPage(1)); hero.addView(act,lp(-1,dp(44))); body.addView(hero); body.addView(section("概览")); LinearLayout stats=row(); stats.addView(stat("歌曲",String.valueOf(tracks.size())),lp(0,dp(84),1)); stats.addView(stat("歌单",String.valueOf(database.playlists().size())),lp(0,dp(84),1)); stats.addView(stat("最近播放",String.valueOf(recent.size())),lp(0,dp(84),1)); body.addView(stats); body.addView(section("最近聆听")); if(recent.isEmpty()) body.addView(text("还没有播放记录",14,MUTED),lp(-1,dp(48))); else addRows(body,recent,5); body.addView(section("快捷入口")); Button lists=button("管理我的歌单"); lists.setOnClickListener(v->switchPage(2)); body.addView(lists,lp(-1,dp(44))); }
    private void renderLibrary() { LinearLayout actions=row(); Button scan=button("扫描音乐"); scan.setOnClickListener(v->scanMediaStore()); actions.addView(scan,lp(0,dp(44),1)); Button eq=button("均衡器"); eq.setOnClickListener(v->showEqualizerDialog()); LinearLayout.LayoutParams ep=lp(0,dp(44),1); ep.setMargins(dp(8),0,0,0); actions.addView(eq,ep); pageHost.addView(actions); search=new EditText(this); search.setHint("搜索歌曲、艺人或专辑"); search.setTextColor(Color.WHITE); search.setHintTextColor(MUTED); search.setTextSize(15); search.setSingleLine(true); search.setInputType(InputType.TYPE_CLASS_TEXT); search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){} public void onTextChanged(CharSequence s,int a,int b,int c){refreshLibraryRows();} public void afterTextChanged(android.text.Editable e){}}); pageHost.addView(search,lp(-1,dp(52))); status=text(tracks.size()+" 首歌曲",13,MINT); status.setPadding(0,dp(10),0,dp(10)); pageHost.addView(status); ScrollView scroll=new ScrollView(this); LinearLayout list=column(); list.setTag("library-list"); scroll.addView(list); pageHost.addView(scroll,lp(-1,0,1)); refreshLibraryRows(); }
    private void refreshLibraryRows() { if(page!=1)return; View view=pageHost.findViewWithTag("library-list"); if(!(view instanceof LinearLayout))return; LinearLayout list=(LinearLayout)view; list.removeAllViews(); String q=search==null?"":search.getText().toString().trim().toLowerCase(Locale.ROOT); List<LibraryDbHelper.Track> visible=new ArrayList<>(); for(LibraryDbHelper.Track t:tracks)if(q.isEmpty()||(t.title+" "+t.artist+" "+t.album).toLowerCase(Locale.ROOT).contains(q))visible.add(t); addRows(list,visible,visible.size()); if(visible.isEmpty())list.addView(text("还没有找到音乐\n点击上方“扫描音乐”导入设备歌曲",16,MUTED),lp(-1,dp(180))); }
    private void renderPlaylists() { Button create=button("＋ 创建歌单"); create.setOnClickListener(v->showCreatePlaylist()); pageHost.addView(create,lp(-1,dp(44))); ScrollView scroll=new ScrollView(this); LinearLayout list=column(); scroll.addView(list); pageHost.addView(scroll,lp(-1,0,1)); List<LibraryDbHelper.Playlist> pls=database.playlists(); if(pls.isEmpty())list.addView(text("还没有歌单\n点击上方创建你的第一个歌单",16,MUTED),lp(-1,dp(180))); for(LibraryDbHelper.Playlist p:pls){LinearLayout c=card(); TextView n=text(p.name,18,Color.WHITE); n.setTypeface(null,1); c.addView(n); c.addView(text(p.count+" 首歌曲",13,MUTED)); LinearLayout buttons=row(); Button play=button("播放"); play.setOnClickListener(v->{List<LibraryDbHelper.Track> items=database.playlistTracks(p.id); if(!items.isEmpty())play(items.get(0),items);}); buttons.addView(play,lp(0,dp(40),1)); Button more=button("管理"); more.setOnClickListener(v->showPlaylistActions(p)); LinearLayout.LayoutParams mp=lp(0,dp(40),1); mp.setMargins(dp(8),0,0,0); buttons.addView(more,mp); c.addView(buttons); list.addView(c,lp(-1,-2));} }
    private void renderSettings() { ScrollView scroll=new ScrollView(this); LinearLayout body=column(); body.setPadding(0,dp(16),0,dp(16)); scroll.addView(body); pageHost.addView(scroll,lp(-1,0,1)); body.addView(section("播放与音质")); body.addView(setting("均衡器","十段原生均衡器和预设曲线",v->showEqualizerDialog())); body.addView(setting("播放服务","MediaSession、通知栏和后台自动下一首",null)); body.addView(section("本地音乐")); body.addView(setting("扫描设备音乐","读取本地音频、封面和同名 LRC 歌词",v->scanMediaStore())); body.addView(setting("存储空间",tracks.size()+" 首歌曲 · 数据保存在本机",v->showStorageDialog())); body.addView(section("关于 Mintune")); body.addView(setting("关于 Mintune","本地优先音乐播放器 · 版本 0.4.805",v->showAbout())); body.addView(setting("开源许可","感谢使用的开源项目",null)); }
    private void addRows(LinearLayout parent,List<LibraryDbHelper.Track> items,int limit) { for(int i=0;i<Math.min(limit,items.size());i++){LibraryDbHelper.Track t=items.get(i); TextView row=text((t.uri.equals(currentUri())?"▶  ":"○  ")+t.title+"\n     "+t.artist+" · "+t.album,15,Color.WHITE); row.setGravity(Gravity.CENTER_VERTICAL); row.setPadding(dp(14),dp(8),dp(12),dp(8)); row.setBackgroundColor(SURFACE); row.setOnClickListener(v->play(t,tracks)); LinearLayout.LayoutParams p=lp(-1,dp(68)); p.setMargins(0,0,0,dp(6)); parent.addView(row,p);} }
    private String currentUri(){return playingIndex>=0&&playingIndex<tracks.size()?tracks.get(playingIndex).uri:"";}
    private TextView section(String s){TextView t=text(s,17,Color.WHITE);t.setTypeface(null,1);t.setPadding(0,dp(20),0,dp(10));return t;}
    private LinearLayout stat(String a,String b){LinearLayout c=card();TextView v=text(b,22,MINT);v.setTypeface(null,1);c.addView(v);c.addView(text(a,12,MUTED));return c;}
    private LinearLayout setting(String a,String b,View.OnClickListener l){LinearLayout c=card();c.setOnClickListener(l);c.addView(text(a,16,Color.WHITE));c.addView(text(b,13,MUTED));return c;}
    private LinearLayout card(){LinearLayout c=column();c.setPadding(dp(14),dp(12),dp(14),dp(12));c.setBackgroundColor(SURFACE);return c;}
    private void showCreatePlaylist(){EditText input=new EditText(this);input.setHint("歌单名称");input.setTextColor(Color.WHITE);new AlertDialog.Builder(this).setTitle("创建歌单").setView(input).setNegativeButton("取消",null).setPositiveButton("创建",(d,w)->{String n=input.getText().toString().trim();if(!n.isEmpty()){database.createPlaylist(n);switchPage(2);}}).show();}
    private void showPlaylistActions(LibraryDbHelper.Playlist p){new AlertDialog.Builder(this).setTitle(p.name).setItems(new String[]{"重命名","删除"},(d,w)->{if(w==0){EditText in=new EditText(this);in.setText(p.name);in.setTextColor(Color.WHITE);new AlertDialog.Builder(this).setTitle("重命名歌单").setView(in).setNegativeButton("取消",null).setPositiveButton("保存",(x,y)->{if(!in.getText().toString().trim().isEmpty()){database.renamePlaylist(p.id,in.getText().toString().trim());switchPage(2);}}).show();}else{database.deletePlaylist(p.id);switchPage(2);}}).show();}
    private void showStorageDialog(){new AlertDialog.Builder(this).setTitle("存储空间").setMessage("音乐元数据、歌单和播放历史均保存在本地。\n\n当前歌曲："+tracks.size()+" 首").setPositiveButton("知道了",null).show();}
    private void showAbout(){new AlertDialog.Builder(this).setTitle("Mintune").setMessage("本地优先音乐播放器\n版本 0.4.805\n\n你的音乐、歌单和播放记录默认保存在设备本地。").setPositiveButton("知道了",null).show();}
    private void showEqualizerDialog(){LinearLayout panel=column();panel.setPadding(dp(12),dp(4),dp(12),dp(4));Switch enabled=new Switch(this);enabled.setText("启用十段均衡器");enabled.setTextColor(Color.WHITE);enabled.setChecked(true);panel.addView(enabled);String[] bands={"31","63","125","250","500","1k","2k","4k","8k","16k"};for(int i=0;i<10;i++){final int band=i;LinearLayout line=row();line.addView(text(bands[i]+" Hz",12,MUTED),lp(dp(62),dp(42)));SeekBar seek=new SeekBar(this);seek.setMax(24);seek.setProgress(12);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean u){if(u)sendEqualizer(band,p-12);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});line.addView(seek,lp(0,dp(42),1));panel.addView(line);}enabled.setOnCheckedChangeListener((b,c)->sendEqualizerEnabled(c));new AlertDialog.Builder(this).setTitle("均衡器").setView(panel).setNegativeButton("关闭",null).setNeutralButton("重置",(d,w)->{for(int i=0;i<10;i++)sendEqualizer(i,0);}).setPositiveButton("流行预设",(d,w)->{int[] p={3,2,1,0,-1,-1,0,1,2,3};for(int i=0;i<10;i++)sendEqualizer(i,p[i]);}).show();}
    private void sendEqualizer(int band,float gain){startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_SET_EQ).putExtra("band",band).putExtra("gainDb",gain).putExtra("enabled",true));}
    private void sendEqualizerEnabled(boolean e){startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_SET_EQ).putExtra("band",-1).putExtra("enabled",e));}
    private void loadData(){executor.execute(()->{List<LibraryDbHelper.Track> a=database.all(),b=database.recentTracks();runOnUiThread(()->{tracks.clear();tracks.addAll(a);recent.clear();recent.addAll(b);switchPage(page);});});}
    private void scanMediaStore(){statusMessage("正在扫描设备音乐…");executor.execute(()->{String[] cols={MediaStore.Audio.Media._ID,MediaStore.Audio.Media.TITLE,MediaStore.Audio.Media.ARTIST,MediaStore.Audio.Media.ALBUM,MediaStore.Audio.Media.DURATION,MediaStore.Audio.Media.DATA,MediaStore.Audio.Media.DATE_MODIFIED};int n=0;try(Cursor c=getContentResolver().query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,cols,MediaStore.Audio.Media.IS_MUSIC+" != 0",null,MediaStore.Audio.Media.TITLE+" COLLATE NOCASE ASC")){if(c!=null)while(c.moveToNext()){long id=c.getLong(0);String title=safe(c.getString(1),"未知歌曲"),artist=safe(c.getString(2),"未知艺人"),album=safe(c.getString(3),"未知专辑"),path=c.getString(5),uri=ContentUris.withAppendedId(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,id).toString();long modified=c.getLong(6);if(!database.unchanged(uri,modified))database.upsert(uri,title,artist,album,c.getLong(4),modified,coverPath(path),lrcPath(path));n++;if(n%10==0)statusMessage("扫描中 · 已检查 "+n+" 首");}}loadData();});}
    private void statusMessage(String m){runOnUiThread(()->{if(status!=null)status.setText(m);else Toast.makeText(this,m,Toast.LENGTH_SHORT).show();});}
    private String coverPath(String p){File f=CoverResolver.sidecar(p);return f==null?null:f.getAbsolutePath();}
    private String lrcPath(String p){if(p==null)return null;File a=new File(p),f=new File(a.getParentFile(),a.getName().replaceFirst("\\.[^.]+$","")+".lrc");return f.isFile()?f.getAbsolutePath():null;}
    private String safe(String v,String f){return v==null||v.trim().isEmpty()||"<unknown>".equalsIgnoreCase(v)?f:v;}
    private void play(LibraryDbHelper.Track target,List<LibraryDbHelper.Track> queue){int index=-1;for(int i=0;i<tracks.size();i++)if(tracks.get(i).uri.equals(target.uri))index=i;playingIndex=index;ArrayList<String> u=new ArrayList<>(),t=new ArrayList<>(),a=new ArrayList<>();for(LibraryDbHelper.Track x:queue){u.add(x.uri);t.add(x.title);a.add(x.artist);}Intent in=new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_PLAY).putExtra(PlaybackService.EXTRA_URI,target.uri).putExtra(PlaybackService.EXTRA_TITLE,target.title).putExtra(PlaybackService.EXTRA_ARTIST,target.artist).putStringArrayListExtra(PlaybackService.EXTRA_QUEUE_URI,u).putStringArrayListExtra(PlaybackService.EXTRA_QUEUE_TITLE,t).putStringArrayListExtra(PlaybackService.EXTRA_QUEUE_ARTIST,a).putExtra(PlaybackService.EXTRA_QUEUE_INDEX,Math.max(0,queue.indexOf(target)));if(Build.VERSION.SDK_INT>=26)startForegroundService(in);else startService(in);database.addHistory(target.uri);loadData();}
    private boolean hasAudioPermission(){return Build.VERSION.SDK_INT<33?checkSelfPermission(Manifest.permission.READ_EXTERNAL_STORAGE)==PackageManager.PERMISSION_GRANTED:checkSelfPermission(Manifest.permission.READ_MEDIA_AUDIO)==PackageManager.PERMISSION_GRANTED;}
    private void requestAudioPermission(){requestPermissions(Build.VERSION.SDK_INT<33?new String[]{Manifest.permission.READ_EXTERNAL_STORAGE}:new String[]{Manifest.permission.READ_MEDIA_AUDIO,Manifest.permission.POST_NOTIFICATIONS},REQUEST_AUDIO);}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQUEST_AUDIO&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)loadData();}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout row(){return new LinearLayout(this);}
    private TextView text(String v,int s,int c){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);t.setLineSpacing(0,1.15f);return t;}
    private Button button(String v){Button b=new Button(this);b.setText(v);b.setTextSize(13);b.setTextColor(BG);b.setAllCaps(false);b.setMinHeight(0);b.setMinWidth(0);return b;}
    private LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w,h);}
    private LinearLayout.LayoutParams lp(int w,int h,float weight){return new LinearLayout.LayoutParams(w,h,weight);}
    private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
    @Override protected void onDestroy(){executor.shutdownNow();database.close();super.onDestroy();}
}
